-- 2026-10-16 まさ指示: 在庫菌体は既存設備を使い、追加購入した設備だけを費用計上。
-- データのみ。変更前指紋検査付き、一度適用後の再実行禁止。
begin;
select set_config('amd.cost_change_reason','まさ指示: 在庫菌体の既存設備利用と追加購入・開始資金の分離',true);
do $$ begin
 if (select md5(to_jsonb(t)::text) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from '5956ef6a5212f60cfc58077774925693' then raise exception 'fuel data changed: cm_p21_fuel_260914'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_notes t where cost_note_id='cnf_caveat_biomass') is distinct from '626a9accaa6db4dbf96dca0a1195c8bf' then raise exception 'fuel data changed: cnf_caveat_biomass'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_notes t where cost_note_id='cnf_caveat_line') is distinct from '9dfe881ab178d29068fffcbba7fa4c3a' then raise exception 'fuel data changed: cnf_caveat_line'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_notes t where cost_note_id='cnf_guide') is distinct from 'a9fba3edd13bff4cfcc5a839169827ce' then raise exception 'fuel data changed: cnf_guide'; end if;
 if (select md5(to_jsonb(t)::text) from project_cost_assumptions t where cost_assumption_id='caf_op_inventory_incremental_annual') is distinct from 'db02b44e5fc37463342b4bc8ccfb80d7' then raise exception 'fuel data changed: caf_op_inventory_incremental_annual'; end if;
 if exists(select 1 from project_cost_assumptions where cost_model_id='cm_p21_fuel_260914' and role_key='inventory_equipment_capex') then raise exception 'shared equipment inputs already exist'; end if;
end $$;
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_shared_inventory_equipment_capex','cm_p21_fuel_260914',null,'既存設備と追加費用','実際に追加購入する設備の総額',0,null,'円','H','仮置き','AMD（内部）',true,'inventory_equipment_capex','既存設備を使う追加採算の条件として追加購入0円。購入が必要になった設備の総額だけを入力し、耐用年数で割って年間原価へ一度加算する。参考明細の設備を自動購入する計算は使わない。既存設備の利用料・追加保守は追加運転費へ入力する。','amd_internal',118,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_shared_inventory_equipment_life_years','cm_p21_fuel_260914',null,'既存設備と追加費用','追加購入設備の耐用年数',7,null,'年','H','仮置き','AMD（内部）',true,'inventory_equipment_life_years','追加購入する設備を入力した場合の耐用年数。7年を比較用に仮置きし、設備の見積・更新周期で置き換える。','amd_internal',119,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_shared_inventory_initial_working_capital','cm_p21_fuel_260914',null,'既存設備と追加費用','初回の溶媒等の調達資金',null,null,'円','H','仮置き','AMD（内部）',true,'inventory_initial_working_capital','開始時に新たに必要な溶媒の初期在庫などの運転資金。設備費・年間の原価と分けて表示する。未見積は空欄。年内に消耗する溶媒の補給費は既存のOPEX明細で計上する。','amd_internal',120,null,null);
update project_cost_models set version_label='261016 在庫菌体・既存設備の追加採算',summary_md='排水処理で使う年間の新規菌体量から、出荷待ち中の分泌回収によるFAME量を計算する。初期表示は既存の培養・保管・回収・燃料化設備を利用する追加採算。装置の購入・償却と設備価格比の固定保守を自動計上せず、実際に追加購入する設備と追加運転費を入力した分だけ加える。初回溶媒等の調達資金は開始時の運転資金として別表示する。',system_scope_md='排水処理で使う年間の新規菌体量から、出荷待ち中の分泌回収によるFAME量を計算する。初期表示は既存の培養・保管・回収・燃料化設備を利用する追加採算。装置の購入・償却と設備価格比の固定保守を自動計上せず、実際に追加購入する設備と追加運転費を入力した分だけ加える。初回溶媒等の調達資金は開始時の運転資金として別表示する。 作業・薬品・消耗溶媒・電力・品質確認・輸送の費用を計上する。共通培養費の配賦は年額の入力で一度だけ加える。専用培養では設備明細を含む従来の全額計上を使う。排水処理側の保存値と権限は維持する。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='在庫菌体と既存設備を使う追加採算',body_md='在庫菌体の方式では、排水処理側の共通培養設備・培養原料・作業は共通費の年額配賦で扱う。既存の培養・保管・回収・燃料化設備を利用する条件で、設備購入・償却・設備価格比の固定保守は自動計上0円。追加購入する設備の入力額だけを償却し、利用料・追加保守・品質管理などは追加運転費へ入力する。' where cost_note_id='cnf_caveat_line';
update project_cost_notes set title='追加購入設備と初回の運転資金',body_md='在庫方式の設備明細は購入する場合の参考値。初期表示の追加購入は0円で、必要な追加設備の総額を入力した場合だけ耐用年数で割って原価へ加える。既存設備の利用料・追加保守は追加運転費に入れる。初回の溶媒在庫などは開始時の調達資金として別入力・別表示し、設備の償却に含めない。年間に消耗する溶媒の補給費はOPEXの明細で計上する。専用培養では従来の設備計上を使う。' where cost_note_id='cnf_caveat_biomass';
update project_cost_notes set title='排水処理の菌体量からFAME量と追加原価を見る',body_md='排水事業に連動する条件では、排水処理で使う新しい菌体量から年間FAME量を出す。排水側の保存前の試算と株・用途も反映する。在庫方式の初期表示は既存設備を利用する追加採算で、作業・薬品・消耗溶媒・電力・品質確認・輸送を積上げる。実際に追加購入する設備は総額と耐用年数、利用料・追加保守は追加運転費、初回の溶媒等は開始資金へ入力する。光源と専用培養の比較も切り替えられる。' where cost_note_id='cnf_guide';
update project_cost_assumptions set label='追加運転費（設備利用・保守・品質等）',note='既存設備の利用料・追加保守・株の維持・追加品質管理・出荷への影響など、既存明細にない年間差額。実際に増える費用を入力する。作業・薬品・溶媒の消耗など明細に計上済みの額と重複させない。空欄は未見積。',updated_at=now() where cost_assumption_id='caf_op_inventory_incremental_annual';
commit;
